package main

// controllerFileTemplate renders a full, standalone Go file (package clause,
// imports, and reconciler) for a single typeNeeded. Every reconciler lives in
// its own file, so the import block is generated per-type, only pulling in
// what that type's reconciler body actually uses.
var controllerFileTemplate = `
// Code generated by Kong; DO NOT EDIT.

package onpremconfig

import (
	"context"
	"time"

	"github.com/go-logr/logr"
	apierrors "k8s.io/apimachinery/pkg/api/errors"
	"k8s.io/apimachinery/pkg/runtime"
{{- if .ConfigStatusNotificationsEnabled }}
	"k8s.io/apimachinery/pkg/runtime/schema"
{{- end}}
	"k8s.io/apimachinery/pkg/types"
	ctrl "sigs.k8s.io/controller-runtime"
	"sigs.k8s.io/controller-runtime/pkg/builder"
	"sigs.k8s.io/controller-runtime/pkg/client"
	"sigs.k8s.io/controller-runtime/pkg/controller"
{{- if .ConfigStatusNotificationsEnabled }}
	"sigs.k8s.io/controller-runtime/pkg/handler"
{{- end}}
	"sigs.k8s.io/controller-runtime/pkg/reconcile"
{{- if .ConfigStatusNotificationsEnabled }}
	"sigs.k8s.io/controller-runtime/pkg/source"
{{- end}}

	ctrlconsts "github.com/kong/kong-operator/v2/controller/consts"
	"github.com/kong/kong-operator/v2/ingress-controller/pkg/controllers"
{{- if .ProgrammedCondition.UpdatesEnabled }}
	ctrlutils "github.com/kong/kong-operator/v2/ingress-controller/pkg/controllerutils"
{{- end}}
{{- if .ConfigStatusNotificationsEnabled }}
	"github.com/kong/kong-operator/v2/ingress-controller/pkg/status"
{{- end}}
	"github.com/kong/kong-operator/v2/modules/manager/logging"
	"github.com/kong/kong-operator/v2/pkg/multiinstance/aigateway/changenotifier"

	{{.PackageImportAlias}} "{{.Package}}"
)

// -----------------------------------------------------------------------------
// {{.PackageAlias}} {{.Kind}} - Reconciler
// -----------------------------------------------------------------------------

// {{.Kind}}Reconciler reconciles {{.Kind}} resources
type {{.Kind}}Reconciler struct {
	client.Client

	Log              logr.Logger
	Scheme           *runtime.Scheme
	DataplaneClient  controllers.DataPlane
	CacheSyncTimeout time.Duration
{{- if .ConfigStatusNotificationsEnabled }}
	StatusQueue      *status.Queue
{{- end}}
	ChangeNotifier   *changenotifier.ChangeNotifier
	Cache            map[types.NamespacedName]types.NamespacedName
}

var _ controllers.Reconciler = &{{.Kind}}Reconciler{}

// SetupWithManager sets up the controller with the Manager.
func (r *{{.Kind}}Reconciler) SetupWithManager(mgr ctrl.Manager) error {
	blder := ctrl.NewControllerManagedBy(mgr).
		// set the controller name
		Named("{{.PackageAlias}}{{.Kind}}").
		WithOptions(controller.Options{
			LogConstructor: func(_ *reconcile.Request) logr.Logger {
				return r.Log
			},
			CacheSyncTimeout: r.CacheSyncTimeout,
	    })

{{- if .ConfigStatusNotificationsEnabled }}
	// if configured, start the status updater controller
	if r.StatusQueue != nil {
		blder.WatchesRawSource(
			source.Channel(
				r.StatusQueue.Subscribe(schema.GroupVersionKind{
					Group:   "{{.Group}}",
					Version: "{{.Version}}",
					Kind:    "{{.Kind}}",
				}),
				&handler.EnqueueRequestForObject{},
			),
		)
	}
{{- end}}
	return blder.
		For(
			&{{.PackageImportAlias}}.{{.Kind}}{},
			builder.WithPredicates(
				GenerationChangedPredicate{},
			),
		).
		Complete(r)
}

// SetLogger sets the logger.
func (r *{{.Kind}}Reconciler) SetLogger(l logr.Logger) {
	r.Log = l
}

// SetCommonFields sets the shared controller dependencies.
func (r *{{.Kind}}Reconciler) SetCommonFields(
	client client.Client,
	scheme *runtime.Scheme,
	log logr.Logger,
	cacheSyncTimeout time.Duration,
	changeNotifier *changenotifier.ChangeNotifier,
) {
	r.Client = client
	r.Scheme = scheme
	r.Log = log
	r.CacheSyncTimeout = cacheSyncTimeout
	r.ChangeNotifier = changeNotifier
}

//+kubebuilder:rbac:groups={{.Group}},resources={{.Plural}},verbs={{ .RBACVerbs | join ";" }}
{{- if .NeedsStatusPermissions}}
//+kubebuilder:rbac:groups={{.Group}},resources={{.Plural}}/status,verbs=get;update;patch
{{- end}}

// Reconcile processes the watched objects
func (r *{{.Kind}}Reconciler) Reconcile(ctx context.Context, req ctrl.Request) (ctrl.Result, error) {
	if r.Cache == nil {
		r.Cache = make(map[types.NamespacedName]types.NamespacedName)
	}
	obj := new({{.PackageImportAlias}}.{{.Kind}})
	logger := r.Log.
		WithValues("{{.PackageAlias}}{{.Kind}}", req.NamespacedName).
		WithValues("namespace", req.Namespace).
		WithValues("name", req.Name).
		V(logging.DebugLevel.Value())
	logger.Info("Reconciling resource")

	if err := r.Get(ctx, req.NamespacedName, obj); err != nil {
		if apierrors.IsNotFound(err) {
			// The parent was stored on the previous reconcile, so that the deletion
			// notification still carries the gateway to re-render, even though the
			// object (and its parent reference) is already gone from the API server.
			if parent, ok := r.Cache[req.NamespacedName]; ok {
				obj.Namespace = req.Namespace
				obj.Name = req.Name
				obj.Kind = "{{.Kind}}"
				if r.ChangeNotifier != nil {
					r.ChangeNotifier.NotifyChange(ctx, &parent, obj)
				}
				delete(r.Cache, req.NamespacedName)
			}
			return ctrl.Result{}, nil
		}
		return ctrl.Result{}, err
	}

	parent := types.NamespacedName{}
	targetsOnPrem := false
	if ref := obj.GetAIGatewayRef(); ref.TargetsOnPremAIGateway() && ref.NamespacedRef != nil {
		targetsOnPrem = true
		parent.Namespace = obj.Namespace
		if ref.NamespacedRef.Namespace != nil {
			parent.Namespace = *ref.NamespacedRef.Namespace
		}
		parent.Name = ref.NamespacedRef.Name
	}

	previous, hadPrevious := r.Cache[req.NamespacedName]
	if targetsOnPrem {
		if hadPrevious && previous != parent {
			// The entity was repointed at a different OnPremAIGateway: notify the
			// previously referenced one so it re-renders without the entity.
			if r.ChangeNotifier != nil {
				r.ChangeNotifier.NotifyChange(ctx, &previous, obj)
			}
		}
		r.Cache[req.NamespacedName] = parent
	} else {
		if hadPrevious {
			// The entity no longer targets an OnPremAIGateway (it was deleted or
			// repointed at a KonnectAIGateway): notify the previously referenced
			// gateway so it re-renders without the entity, then forget it.
			delete(r.Cache, req.NamespacedName)
			if r.ChangeNotifier != nil {
				r.ChangeNotifier.NotifyChange(ctx, &previous, obj)
			}
		}
		// Entities referencing a KonnectAIGateway are owned by the Konnect
		// reconciler, not the on-prem machinery.
		return ctrl.Result{}, nil
	}

	if r.ChangeNotifier != nil {
		r.ChangeNotifier.NotifyChange(ctx, &parent, obj)
	}

	// clean the object up if it's being deleted
	if !obj.DeletionTimestamp.IsZero() && time.Now().After(obj.DeletionTimestamp.Time) {
		logger.Info("Resource is being deleted, its configuration will be removed")
		return ctrl.Result{}, nil
	}

{{- if .ConfigStatusNotificationsEnabled }}
	// if status updates are enabled report the status for the object
	if r.DataplaneClient != nil && r.DataplaneClient.AreKubernetesObjectReportsEnabled() {
		{{- if .ProgrammedCondition.UpdatesEnabled }}
		configurationStatus := r.DataplaneClient.KubernetesObjectConfigurationStatus(obj)
		logger.Info("Updating programmed condition status", "configuration_status",configurationStatus)
		conditions, updateNeeded := ctrlutils.EnsureProgrammedCondition(
			configurationStatus,
			obj.Generation,
			obj.Status.Conditions,
		{{- if .ProgrammedCondition.CustomUnknownMessage }}
			ctrlutils.WithUnknownMessage("{{ .ProgrammedCondition.CustomUnknownMessage }}"),
		{{- end }}
		)
		obj.Status.Conditions = conditions
		{{- end }}
		if updateNeeded {
			if err := r.Status().Update(ctx, obj); err != nil {
				if apierrors.IsConflict(err) {
					return ctrl.Result{
						RequeueAfter: ctrlconsts.RequeueWithoutBackoff,
					}, nil
				}
				return ctrl.Result{}, err
			}

			return ctrl.Result{
				RequeueAfter: ctrlconsts.RequeueWithoutBackoff,
			}, nil
		}

		logger.Info("Status update not needed")
	}
{{- end}}

	return ctrl.Result{}, nil
}
`
